def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm. With ``typed=True`` each input tuple is mapped to a separate caching result.
    """

    def decore(func):
        cache = LRU(maxsize, typed=typed)

        @wraps(func)
        def wrapper(*args):
            key = pickle.dumps(args)
            if key in cache:
                return cache[key]
            else:
                value = func(*args)
                cache[key] = value
                return value

        return wrapper

    return decore
