def identify_request(request):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request.method == 'POST' and 'message_type' in request.data:
            return '[Public DS Message]'
        elif request.method == 'POST' and 'payload' in request.data and 'legacy' in request.data['payload']:
